,"reward_steps":2,"pose":"R02","remote":true,"together":true,"estimated_cost_eur":0}]$US_TWO_137$::jsonb)
AS c(id text,world smallint,title text,category text,minutes smallint,reward_steps smallint,pose text,remote boolean,together boolean,brief text,remote_instructions text,together_instructions text,estimated_cost_eur integer)
ON CONFLICT (id) DO NOTHING;
DO $US_TWO_CHECK$
DECLARE total_rows integer;
DECLARE per_world integer;
DECLARE w integer;
BEGIN
 SELECT count(*) INTO total_rows FROM public.us_quest_catalog;
 IF total_rows <> 240 THEN RAISE EXCEPTION 'Expected 240 activities, got %',total_rows; END IF;
 FOR w IN 0..5 LOOP
  SELECT count(*) INTO per_world FROM public.us_quest_catalog WHERE world=w;
  IF per_world<>40 THEN RAISE EXCEPTION 'World % has % cards instead of 40',w,per_world; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.us_quest_catalog WHERE nullif(trim(remote_instructions),'') IS NULL OR nullif(trim(together_instructions),'') IS NULL)
 THEN RAISE EXCEPTION 'Missing activity instructions in catalog'; END IF;
END
$US_TWO_CHECK$;
